mapper.select:
select b.id as id, b.org_id as orgId, b.org_name as orgName, b.case_entry_time as caseEntryTime, b.sign_time as signTime, b.salesman_id as salesmanId, b.salesman_name as salesmanName, b.case_no as caseNo, b.case_state as caseState, b.gradation_state as gradationState, b.client_name as clientName, b.contract_summary as contractSummary, b.estimate_service_money as estimateServiceMoney, b.check_service_money as checkServiceMoney, b.re_basic_money as reBasicMoney, b.re_tail_money as reTailMoney, b.re_interest_money as reInterestMoney, b.re_other_money as reOtherMoney, b.re_total_money as reTotalMoney, b.basic_money as basicMoney, b.basic_money_time as basicMoneyTime, b.other_cost_money as otherCostMoney, b.return_money as returnMoney, b.return_money_time as returnMoneyTime, b.return_total_money as returnTotalMoney, b.total_service_money as totalServiceMoney, b.billing_code as billingCode, b.billing_money as billingMoney, b.billing_time as billingTime, b.billing_total_money as billingTotalMoney, b.is_loan as isLoan, b.loan_money as loanMoney, b.loan_company as loanCompany, b.loan_time as loanTime, b.real_loan_money as realLoanMoney, b.insurance_money as insuranceMoney, b.interest_money as interestMoney, b.injured_money as injuredMoney, b.real_interest_money as realInterestMoney, b.claim_name as claimName, b.claim_time as claimTime, b.is_closed as isClosed, b.closed_time as closedTime, b.is_commission as isCommission, b.commission_money as commissionMoney, b.commission_time as commissionTime, b.litigation_money as litigationMoney, b.litigation_time as litigationTime, b.maintain_money as maintainMoney, b.maintain_time as maintainTime, b.other_cost_time as otherCostTime, b.re_loan_money as reLoanMoney, b.re_loan_time as reLoanTime, (IFNULL(b.litigation_money,0.00) + IFNULL(b.commission_money,0.00) + IFNULL(b.maintain_money,0.00) + IFNULL(b.real_interest_money,0.00) + IFNULL(b.other_cost_money,0.00)) as costTotle from case_personal_cw_info b
and b.org_id = #{orgId,jdbcType=BIGINT}
and b.case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')
and b.salesman_name like concat('%',#{salesmanName,jdbcType=VARCHAR},'%')
and b.client_name like concat('%',#{clientName,jdbcType=VARCHAR},'%')
and b.gradation_state = #{gradationState,jdbcType=VARCHAR}
order by b.id desc limit #{pageIndex} , #{pageSize}

select count(1) from case_personal_cw_info b


        and b.org_id = #{orgId,jdbcType=BIGINT}


        and b.case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')


        and b.salesman_name like concat('%',#{salesmanName,jdbcType=VARCHAR},'%')


        and b.client_name like concat('%',#{clientName,jdbcType=VARCHAR},'%')


        and b.gradation_state = #{gradationState,jdbcType=VARCHAR}
